
/* ==========================================================================
   UniStyleDB — Βάση δεδομένων eshop ρούχων (2024–2025)
   «Βάσεις Δεδομένων και Επιχειρηματική Αναλυτική» · Πανεπιστήμιο Πειραιώς
   Δρ. Αθανάσιος Κρανιάς · Χειμερινό εξάμηνο 2026–27

   ΣΗΜΑΝΤΙΚΟ: Η εταιρεία, οι πελάτες και όλα τα δεδομένα είναι ΦΑΝΤΑΣΤΙΚΑ
   (συνθετικά), για εκπαιδευτική χρήση. Ίδια δεδομένα με το αρχείο
   UniStyle_eShop_Data.xlsx.

   Εκτέλεση: SSMS → File → Open → File… → Execute (F5).
   Απαιτεί SQL Server 2016 ή νεότερο.
   ========================================================================== */

USE master;
GO
DROP DATABASE IF EXISTS UniStyleDB;
GO
CREATE DATABASE UniStyleDB;
GO
USE UniStyleDB;
GO

/* ---------- Πόλεις & περιφέρειες ---------- */
CREATE TABLE Cities (
    City        NVARCHAR(50)  NOT NULL PRIMARY KEY,
    Region      NVARCHAR(60)  NOT NULL
);

/* ---------- Πελάτες ----------
   Η στήλη City είναι όπως την πληκτρολόγησε ο πελάτης (χωρίς ξένο κλειδί):
   για να συνδεθεί με τον πίνακα Cities, πρέπει πρώτα να καθαριστεί. */
CREATE TABLE Customers (
    CustomerID  INT           NOT NULL PRIMARY KEY,
    FirstName   NVARCHAR(50)  NOT NULL,
    LastName    NVARCHAR(50)  NOT NULL,
    Gender      CHAR(1)       NOT NULL CHECK (Gender IN ('F', 'M')),
    BirthDate   DATE          NULL,
    City        NVARCHAR(50)  NOT NULL,
    Email       VARCHAR(100)  NOT NULL UNIQUE,
    SignupDate  DATE          NOT NULL,
    Newsletter  VARCHAR(3)    NOT NULL CHECK (Newsletter IN ('Yes', 'No'))
);

/* ---------- Προϊόντα ---------- */
CREATE TABLE Products (
    ProductID   INT           NOT NULL PRIMARY KEY,
    ProductName NVARCHAR(50)  NOT NULL,
    Category    NVARCHAR(30)  NOT NULL,
    Gender      NVARCHAR(10)  NOT NULL CHECK (Gender IN ('Women', 'Men', 'Unisex')),
    Brand       NVARCHAR(30)  NOT NULL,
    Color       NVARCHAR(20)  NOT NULL,
    Season      NVARCHAR(20)  NOT NULL,
    CostPrice   DECIMAL(10,2) NOT NULL CHECK (CostPrice > 0),
    ListPrice   DECIMAL(10,2) NOT NULL,
    CHECK (ListPrice > CostPrice)
);

/* ---------- Παραγγελίες (κεφαλίδα) ---------- */
CREATE TABLE Orders (
    OrderID        INT           NOT NULL PRIMARY KEY,
    CustomerID     INT           NOT NULL REFERENCES Customers(CustomerID),
    OrderDate      DATE          NOT NULL,
    Channel        VARCHAR(10)   NOT NULL CHECK (Channel IN ('Web', 'App')),
    PaymentMethod  VARCHAR(20)   NOT NULL,
    ShippingMethod VARCHAR(20)   NOT NULL,
    ShippingCost   DECIMAL(6,2)  NOT NULL DEFAULT 0,
    Status         VARCHAR(15)   NOT NULL CHECK (Status IN ('Delivered', 'Cancelled'))
);

/* ---------- Γραμμές παραγγελιών (ενδιάμεσος πίνακας N:M Orders–Products) ---------- */
CREATE TABLE OrderItems (
    OrderItemID  INT           NOT NULL PRIMARY KEY,
    OrderID      INT           NOT NULL REFERENCES Orders(OrderID),
    ProductID    INT           NOT NULL REFERENCES Products(ProductID),
    Size         VARCHAR(10)   NOT NULL,
    Quantity     INT           NOT NULL CHECK (Quantity > 0),
    UnitPrice    DECIMAL(10,2) NOT NULL,
    DiscountPct  DECIMAL(4,2)  NOT NULL DEFAULT 0 CHECK (DiscountPct BETWEEN 0 AND 1),
    Returned     BIT           NOT NULL DEFAULT 0,
    ReturnReason NVARCHAR(30)  NULL
);
GO

