/* ---------- Έλεγχος 1: πόσες γραμμές έχει κάθε πίνακας ---------- */
SELECT 'Cities' AS TableName, COUNT(*) AS NumRows FROM Cities
UNION ALL SELECT 'Customers',  COUNT(*) FROM Customers
UNION ALL SELECT 'Products',   COUNT(*) FROM Products
UNION ALL SELECT 'Orders',     COUNT(*) FROM Orders
UNION ALL SELECT 'OrderItems', COUNT(*) FROM OrderItems;

/* ---------- Έλεγχος 2: καθαρές πωλήσεις ανά έτος (ίδιες με τη «Σύνοψη» του Excel) ---------- */
SELECT YEAR(o.OrderDate) AS SalesYear,
       SUM(ROUND(i.Quantity * i.UnitPrice * (1 - i.DiscountPct), 2)) AS NetSales
FROM   OrderItems AS i
JOIN   Orders     AS o ON o.OrderID = i.OrderID
WHERE  o.Status = 'Delivered'
GROUP BY YEAR(o.OrderDate)
ORDER BY SalesYear;
